def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count K-move paths through distinct orthogonally adjacent empty cells.

    H and W are between 1 and 10, and K is between 1 and 11.
    Every empty starting cell is allowed; reversed paths count separately.
    """
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == '.']
    if len(cells) <= K:
        return 0

    index = {cell: i for i, cell in enumerate(cells)}
    neighbors = []
    for r, c in cells:
        neighbors.append([
            index[(nr, nc)]
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
            if (nr, nc) in index
        ])
    bits = [1 << i for i in range(len(cells))]

    def dfs(cell: int, remaining: int, visited: int) -> int:
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[cell]:
            bit = bits[nxt]
            if not visited & bit:
                total += dfs(nxt, remaining - 1, visited | bit)
        return total

    return sum(dfs(start, K, bits[start]) for start in range(len(cells)))

from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by their LCS length with s.

    Return n+1 counts modulo 998244353. The constraints are
    1 <= n <= 10, 1 <= m <= 100, and len(s) == n.
    """
    mod = 998244353
    positions = {}
    for i, char in enumerate(s):
        positions[char] = positions.get(char, 0) | (1 << i)

    # A bit at i records an increase between adjacent entries of the
    # LCS row for prefixes s[:i] and s[:i+1]. Thus only 2**n rows exist.
    size = 1 << n
    transitions = []
    for state in range(size):
        counts = {state: 26 - len(positions)}
        for matches in positions.values():
            x = state | matches
            target = x & ~(x - ((state << 1) | 1))
            counts[target] = counts.get(target, 0) + 1
        transitions.append(tuple(counts.items()))

    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        next_dp = [0] * size
        for state, count in enumerate(dp):
            if count:
                for target, multiplicity in transitions[state]:
                    next_dp[target] += count * multiplicity
        dp = [count % mod for count in next_dp]

    answer = [0] * (n + 1)
    for state, count in enumerate(dp):
        answer[state.bit_count()] += count
    return [count % mod for count in answer]

def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether insertions, deletions and replacements can turn s into t
    using at most k operations.

    Keep the farthest reachable source position on each edit-graph diagonal
    after each number of edits, extending every state across equal characters.
    There are O(k**2) frontier states and O(k * (len(s) + len(t))) work,
    with O(k) additional space.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t or max(n, m) <= k:
        return True

    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    # A diagonal is x - y, where x and y are consumed prefix lengths.
    frontier = {0: x}
    for edits in range(1, k + 1):
        next_frontier = {}
        for diagonal, x in frontier.items():
            y = x - diagonal
            if x < n:
                # Delete a source character.
                d = diagonal + 1
                next_frontier[d] = max(next_frontier.get(d, -1), x + 1)
            if y < m:
                # Insert the next target character.
                d = diagonal - 1
                next_frontier[d] = max(next_frontier.get(d, -1), x)
            if x < n and y < m:
                # Replace the next source character.
                next_frontier[diagonal] = max(
                    next_frontier.get(diagonal, -1), x + 1
                )

        frontier = {}
        for diagonal, x in next_frontier.items():
            y = x - diagonal
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if x == n and y == m:
                return True
            # The remaining length difference is an unavoidable edit cost.
            if abs((n - x) - (m - y)) <= k - edits:
                frontier[diagonal] = x
        if not frontier:
            return False
    return False

