from functools import lru_cache


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers x in [num1, num2] with digit sum in [min_sum, max_sum].

    Return the count modulo 10^9 + 7.

    Args:
        num1: A numeric string representing the lower bound (1 <= num1 <= 10^22)
        num2: A numeric string representing the upper bound (num1 <= num2 <= 10^22)
        min_sum: The minimum allowed digit sum (1 <= min_sum <= 400)
        max_sum: The maximum allowed digit sum (min_sum <= max_sum <= 400)

    Returns:
        The number of good integers modulo 10^9 + 7

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    mod = 10**9 + 7

    def count_up_to(bound):
        digits = tuple(map(int, bound))
        length = len(digits)

        @lru_cache(None)
        def dp(pos, total, tight):
            if total > max_sum or total + 9 * (length - pos) < min_sum:
                return 0
            if pos == length:
                return int(min_sum <= total <= max_sum)
            limit = digits[pos] if tight else 9
            return sum(
                dp(pos + 1, total + digit, tight and digit == limit)
                for digit in range(limit + 1)
            ) % mod

        # Leading zeroes give every integer exactly one representation.
        return dp(0, 0, True)

    lower_is_good = min_sum <= sum(map(int, num1)) <= max_sum
    return (count_up_to(num2) - count_up_to(num1) + lower_is_good) % mod

def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements with at least k deletable nonempty substrings.

    A good string can be emptied by deleting equal pairs and triples ABC.
    Equivalently, its three character counts have the same parity.
    Return the count modulo 998244353, for 1 <= n <= 50.
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)
    # Consecutive prefix classes differ. The largest possible number of
    # equal-class prefix pairs is attained by alternating two classes.
    if k > n * n // 4:
        return 0

    # A, B, C are the three nonzero elements of the Klein four group.
    # Equal prefix XORs delimit precisely the good substrings.
    # Normalize each state so the current prefix is class zero. This
    # removes the need to store the current XOR as another state dimension.
    dp = {(1, 0, 0, 0): 1}
    for ch in s:
        nxt = {}
        choices = (1, 2, 3) if ch == '?' else ({'A': 1, 'B': 2, 'C': 3}[ch],)
        for (a, b, c, d), ways in dp.items():
            for v in choices:
                if v == 1:
                    state = (b + 1, a, d, c)
                elif v == 2:
                    state = (c + 1, d, a, b)
                else:
                    state = (d + 1, c, b, a)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
        dp = nxt

    answer = 0
    for counts, ways in dp.items():
        good = sum(x * (x - 1) // 2 for x in counts)
        if good >= k:
            answer += ways
    return answer % mod

