from math import gcd
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any coin denomination.

    Coins cannot be combined across denominations. There are 1-15 distinct
    positive denominations, each at most 25, and 1 <= k <= 2 * 10**9.

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # Multiples of a retained divisor already cover a redundant denomination.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % divisor == 0 for divisor in denominations):
            denominations.append(coin)

    if len(denominations) == 1:
        return denominations[0] * k

    # Group inclusion-exclusion subsets sharing the same least common multiple.
    # Adding c changes the union count U into U + multiples(c) - U intersect c.
    coefficients = {}
    for coin in denominations:
        additions = {coin: 1}
        for divisor, coefficient in coefficients.items():
            common = divisor // gcd(divisor, coin) * coin
            additions[common] = additions.get(common, 0) - coefficient
        for divisor, coefficient in additions.items():
            coefficients[divisor] = coefficients.get(divisor, 0) + coefficient
            if coefficients[divisor] == 0:
                del coefficients[divisor]

    terms = tuple(coefficients.items())
    low, high = 1, denominations[0] * k
    while low < high:
        middle = (low + high) // 2
        count = sum(coefficient * (middle // divisor)
                    for divisor, coefficient in terms)
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Return the shortest tile-adjacency distance in the alternating strip tiling.

    Coordinates identify the tile containing (x + 0.5, y + 0.5).
    K is between 2 and 10**16; coordinates may be negative.
    """
    si, sx = divmod(S_x, K)
    sj, sy = divmod(S_y, K)
    ti, tx = divmod(T_x, K)
    tj, ty = divmod(T_y, K)

    if K == 2:
        # Every tile is a boundary tile. Represent a horizontal tile by
        # its unit horizontal edge in the grid of K-by-K block corners,
        # and similarly for vertical tiles.
        def tile(i, j, x, y):
            if (i + j) % 2 == 0:
                return (0, i, j + y)
            return (1, i + x, j)

        start = tile(si, sj, sx, sy)
        target = tile(ti, tj, tx, ty)
        if start == target:
            return 0

        def neighbors(state):
            orientation, x, y = state
            if orientation == 0:
                for u in (x, x + 1):
                    for v in (y - 1, y):
                        yield (1, u, v)
                yield (0, x, y + (1 if (x + y) % 2 == 0 else -1))
            else:
                for u in (x - 1, x):
                    for v in (y, y + 1):
                        yield (0, u, v)
                yield (1, x + (1 if (x + y) % 2 else -1), y)

        # Between equal orientation/parity states, even block displacements
        # (a,b) cost (3*max(|a|,|b|) + min(|a|,|b|))/2:
        # axial two-block steps cost 3, diagonal ones cost 4.
        # A shortest route consists of such a periodic part and a terminal
        # adjustment of at most five edges.
        queue = [(target, 0)]
        seen = {target}
        answer = None
        for state, distance in queue:
            o, x, y = state
            if o == start[0] and (x - start[1]) % 2 == 0 and (y - start[2]) % 2 == 0:
                a, b = abs(x - start[1]), abs(y - start[2])
                cost = distance + (3 * max(a, b) + min(a, b)) // 2
                if answer is None or cost < answer:
                    answer = cost
            if distance < 5:
                for nxt in neighbors(state):
                    if nxt not in seen:
                        seen.add(nxt)
                        queue.append((nxt, distance + 1))
        return answer

    def portals(i, j, x, y):
        # (orientation, edge x, edge y, cost from endpoint).
        if (i + j) % 2 == 0:
            return [(0, i, j, y), (0, i, j + 1, K - 1 - y),
                    (1, i, j, 1), (1, i + 1, j, 1)]
        return [(1, i, j, x), (1, i + 1, j, K - 1 - x),
                (0, i, j, 1), (0, i, j + 1, 1)]

    def edge_distance(a, b):
        oa, x, y, _ = a
        ob, u, v, _ = b
        if oa == ob:
            return 2 * max(abs(x - u), abs(y - v))
        if oa == 1:
            x, y, u, v = u, v, x, y
        # A vertical edge meets horizontal edges with bases in
        # [u-1,u] x [v,v+1].
        dx = max(u - 1 - x, x - u, 0)
        dy = max(v - y, y - v - 1, 0)
        return 1 + 2 * max(dx, dy)

    answer = min(a[3] + b[3] + edge_distance(a, b)
                 for a in portals(si, sj, sx, sy)
                 for b in portals(ti, tj, tx, ty))
    if si == ti and sj == tj:
        direct = abs(sy - ty) if (si + sj) % 2 == 0 else abs(sx - tx)
        answer = min(answer, direct)
    return answer

