from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by their LCS length with s.

    Return n+1 counts modulo 998244353. The constraints are
    1 <= n <= 10, 1 <= m <= 100, and len(s) == n.
    """
    mod = 998244353
    positions = {}
    for i, char in enumerate(s):
        positions[char] = positions.get(char, 0) | (1 << i)

    # A bit at i records an increase between adjacent entries of the
    # LCS row for prefixes s[:i] and s[:i+1]. Thus only 2**n rows exist.
    size = 1 << n
    transitions = []
    for state in range(size):
        counts = {state: 26 - len(positions)}
        for matches in positions.values():
            x = state | matches
            target = x & ~(x - ((state << 1) | 1))
            counts[target] = counts.get(target, 0) + 1
        transitions.append(tuple(counts.items()))

    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        next_dp = [0] * size
        for state, count in enumerate(dp):
            if count:
                for target, multiplicity in transitions[state]:
                    next_dp[target] += count * multiplicity
        dp = [count % mod for count in next_dp]

    answer = [0] * (n + 1)
    for state, count in enumerate(dp):
        answer[state.bit_count()] += count
    return [count % mod for count in answer]

def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements having at least k reducible nonempty substrings.

    Identical pairs and ABC triples may be deleted in any positions.
    Return the answer modulo 998244353, for 1 <= n <= 50.
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)
    # Consecutive prefix states differ. Concentrating their visits on two
    # alternating states maximizes the number of equal-prefix pairs.
    if k > n * n // 4:
        return 0

    # Map A, B, C to the three nonzero elements of (Z/2Z)^2.
    # A substring reduces to empty iff its three counts have equal parity,
    # equivalently its mapped xor is zero. Thus its two prefix states agree.
    # Translate all prefix states by the current one, keeping it at state 0.
    # The tuple records visits to each of the four translated states.
    dp = {(1, 0, 0, 0): 1}
    for ch in s:
        following = {}
        choices = (1, 2, 3) if ch == '?' else ({'A': 1, 'B': 2, 'C': 3}[ch],)
        for (a, b, c, d), ways in dp.items():
            for step in choices:
                if step == 1:
                    state = (b + 1, a, d, c)
                elif step == 2:
                    state = (c + 1, d, a, b)
                else:
                    state = (d + 1, c, b, a)
                following[state] = (following.get(state, 0) + ways) % mod
        dp = following
    return sum(ways for counts, ways in dp.items()
               if sum(c * (c - 1) // 2 for c in counts) >= k) % mod

