from functools import lru_cache


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers x in [num1, num2] with digit sum in [min_sum, max_sum].

    Return the count modulo 10^9 + 7.

    Args:
        num1: A numeric string representing the lower bound (1 <= num1 <= 10^22)
        num2: A numeric string representing the upper bound (num1 <= num2 <= 10^22)
        min_sum: The minimum allowed digit sum (1 <= min_sum <= 400)
        max_sum: The maximum allowed digit sum (min_sum <= max_sum <= 400)

    Returns:
        The number of good integers modulo 10^9 + 7

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    mod = 10**9 + 7

    def count_up_to(bound):
        digits = tuple(map(int, bound))
        length = len(digits)

        @lru_cache(None)
        def dp(pos, total, tight):
            if total > max_sum or total + 9 * (length - pos) < min_sum:
                return 0
            if pos == length:
                return int(min_sum <= total <= max_sum)
            limit = digits[pos] if tight else 9
            return sum(
                dp(pos + 1, total + digit, tight and digit == limit)
                for digit in range(limit + 1)
            ) % mod

        # Leading zeroes give every integer exactly one representation.
        return dp(0, 0, True)

    lower_is_good = min_sum <= sum(map(int, num1)) <= max_sum
    return (count_up_to(num2) - count_up_to(num1) + lower_is_good) % mod

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-colour completions, modulo 998244353.

    Each edge-sharing pair must have different digits. The grid has at
    most 200 cells; fixed digits cannot be changed.
    """
    mod = 998244353
    # Sweep along the longer dimension to minimize the frontier width.
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Each two-bit field records the most recently visited cell in its
    # column. Zero denotes a column not visited yet in the first row.
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            shift = 2 * c
            left_shift = shift - 2
            choices = (1, 2, 3) if grid[r][c] == "?" else (int(grid[r][c]),)
            next_dp = {}
            for state, ways in dp.items():
                above = (state >> shift) & 3
                left = ((state >> left_shift) & 3) if c else 0
                cleared = state - (above << shift)
                for colour in choices:
                    if colour != above and colour != left:
                        new_state = cleared | (colour << shift)
                        next_dp[new_state] = (next_dp.get(new_state, 0) + ways) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by their LCS length with s.

    Return n+1 counts modulo 998244353. The constraints are
    1 <= n <= 10, 1 <= m <= 100, and len(s) == n.
    """
    mod = 998244353
    positions = {}
    for i, char in enumerate(s):
        positions[char] = positions.get(char, 0) | (1 << i)

    # A bit at i records an increase between adjacent entries of the
    # LCS row for prefixes s[:i] and s[:i+1]. Thus only 2**n rows exist.
    size = 1 << n
    transitions = []
    for state in range(size):
        counts = {state: 26 - len(positions)}
        for matches in positions.values():
            x = state | matches
            target = x & ~(x - ((state << 1) | 1))
            counts[target] = counts.get(target, 0) + 1
        transitions.append(tuple(counts.items()))

    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        next_dp = [0] * size
        for state, count in enumerate(dp):
            if count:
                for target, multiplicity in transitions[state]:
                    next_dp[target] += count * multiplicity
        dp = [count % mod for count in next_dp]

    answer = [0] * (n + 1)
    for state, count in enumerate(dp):
        answer[state.bit_count()] += count
    return [count % mod for count in answer]

